        "user": "Research topic: {{#1.title#}}\n\nGenerate exactly 3 Google search queries.\nRules:\n- Each query must be on its own line\n- No numbering, no bullets, no extra text\n- Queries should be meaningfully different angles\nOutput only the 3 lines."
      }
    },
    {
      "id": "3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["raw_queries", ["text", "2"]]
