        "code": "def main(url: str):\n\t# Accept formats like:\n\t# https://github.com/OWNER/REPO\n\t# https://github.com/OWNER/REPO/\n\t# https://github.com/OWNER/REPO/tree/branch\n\t# git@github.com:OWNER/REPO.git (best-effort)\n\timport re\n\tu = (url or '').strip()\n\t# Convert SSH to https-like\n\tm = re.match(r'^git@github\\.com:([^/]+)/([^/]+?)(?:\\.git)?$', u)\n\tif m:\n\t\towner, repo = m.group(1), m.group(2)\n\telse:\n\t\t# Strip query/fragment\n\t\tu = re.sub(r'[?#].*$', '', u)\n\t\t# Normalize\n\t\tu = u.rstrip('/')\n\t\t# Extract owner/repo from github.com\n\t\tm = re.match(r'^https?://github\\.com/([^/]+)/([^/]+)', u)\n\t\tif not m:\n\t\t\traise ValueError('Unsupported URL. Please provide a GitHub repository URL like https://github.com/OWNER/REPO')\n\t\towner, repo = m.group(1), m.group(2)\n\t\trepo = re.sub(r'\\.git$', '', repo)\n\trepo_api_url = f\"https://api.github.com/repos/{owner}/{repo}\"\n\treturn {\n\t\t\"owner\": owner,\n\t\t\"repo\": repo,\n\t\t\"repo_api_url\": repo_api_url\n\t}"
      }
