        ],
        "code": "def main(repo_body: str, repo_api_url: str):\n\timport json\n\tdata = json.loads(repo_body or '{}')\n\tdefault_branch = data.get('default_branch') or 'main'\n\t# Git Trees API: /git/trees/{tree_sha}?recursive=1\n\ttree_api_url = f\"{repo_api_url}/git/trees/{default_branch}?recursive=1\"\n\treturn {\n\t\t\"default_branch\": default_branch,\n\t\t\"tree_api_url\": tree_api_url\n\t}"
